import React from 'react';
import { useAuth } from './hooks/useAuth';
import LoginPage from './pages/LoginPage'; // Vom crea paginile

const App = () => {
    const { user, loading } = useAuth(); // Obține starea utilizatorului

    // Afișează un ecran de încărcare în timp ce verificăm starea Firebase
    if (loading) {
        return <div>Se încarcă aplicația PetPal...</div>;
    }

    return (
        <div>
            {/* Logica principală: Dacă user-ul este logat, arată Dashboard. Altfel, arată Login. */}
            {user ? (
                <h1>Bine ai venit, {user.email}! (Aici va fi Dashboard-ul)</h1>
            ) : (
                <LoginPage /> // Aici va fi formularul de login
            )}
        </div>
    );
};

export default App;
